543	TEST_CASE("L24: resume restores mepc/mcause/mtval/mip/mie via abstract "
544	          "commands, each carrying its drained value on DATA0/DATA1")
545	{
546	  RecordingBus bus;
547	  bus.dmstatus_value = (1u << 9) | (1u << 17);
548	
549	  auto s = rv64_state(0x80001000, 0);
550	  s.mepc   = 0x1111111122222222ULL;
551	  s.mcause = 0x8000000000000007ULL;  // machine timer interrupt cause encoding
552	  s.mtval  = 0x3333333344444444ULL;
553	  s.mip    = 0x0000000000000080ULL;  // MTIP
554	  s.mie    = 0x0000000000000888ULL;  // MTIE | MEIE | MSIE
555	
556	  hybrid::ResumeDriver driver(bus, kScratch);
557	  driver.resume(s);
558	
559	  // Each CSR gets a write-COMMAND (bit 16 set) carrying its value on the
560	  // DATA0/DATA1 written immediately before (same shape as fcsr/mscratch).
561	  const std::pair<uint16_t, uint64_t> want[] = {
562	    {0x341, s.mepc}, {0x342, s.mcause}, {0x343, s.mtval},
563	    {0x344, s.mip},  {0x304, s.mie},
564	  };
565	  for (const auto& [csr, val] : want) {
566	    std::optional<std::size_t> cmd_idx;
567	    for (std::size_t i = 0; i < bus.ops.size(); ++i) {
568	      const auto& op = bus.ops[i];
569	      if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
570	          && (op.value & 0xFFFFu) == hybrid::regno_csr(csr)
571	          && ((op.value >> 16) & 1u)) {
572	        cmd_idx = i;
573	        break;
574	      }
575	    }
576	    REQUIRE(cmd_idx.has_value());
577	    REQUIRE(*cmd_idx >= 2);
578	    const auto& d0 = bus.ops[*cmd_idx - 2];
