803	TEST_CASE("resume with HYBRID_FLAG_V: PB reload sweeps v0..v31 from scratch "
804	          "before the architectural V-CSR restore and counter restore")
805	{
806	  RecordingBus bus;
807	  bus.dmstatus_value = (1u << 9) | (1u << 17);
808	
809	  auto s = rv64_state(0x80001000, 0);
810	  s.flags  |= HYBRID_FLAG_V;
811	  s.vlenb  = 64;
812	  s.vl     = 16;
813	  s.vtype  = 0xC1;   // differs from the sweep's e8/m1 vtype (0xC0)
814	  s.vstart = 7;
815	
816	  // L26: the scratch GPA is the runtime top-of-mmap value (kScratch), passed
817	  // to the driver -- no longer a fixed constant. Assert the sweep stages it.
818	  hybrid::ResumeDriver driver(bus, kScratch);
819	  driver.resume(s);
820	
821	  // (a) every v0..v31 is reloaded via a vle8.v executed in the Program Buffer.
822	  std::vector<int> missing;
823	  std::optional<std::size_t> first_vle_idx, last_vle_idx;
824	  for (uint16_t v = 0; v < 32; ++v) {
825	    const uint32_t want = hybrid::encode_vle8_v(static_cast<uint8_t>(v), 7);
826	    std::optional<std::size_t> at;
827	    for (std::size_t i = 0; i < bus.ops.size(); ++i) {
828	      const auto& op = bus.ops[i];
829	      if (op.kind == DmiOp::Kind::Write && op.reg == hybrid::kProgbuf0
830	          && op.value == want) { at = i; break; }
831	    }
832	    if (!at) { missing.push_back(v); continue; }
833	    if (!first_vle_idx || *at < *first_vle_idx) first_vle_idx = at;
834	    if (!last_vle_idx  || *at > *last_vle_idx)  last_vle_idx  = at;
835	  }
836	  CHECK(missing.empty());
837	  REQUIRE(first_vle_idx.has_value());
838	  REQUIRE(last_vle_idx.has_value());
839	
840	  // (b) the per-register scratch GPA is staged in x7 (base pointer) for the
841	  //     first and last register.
842	  auto x7_gpa_staged = [&](uint64_t gpa) {
843	    for (std::size_t i = 2; i < bus.ops.size(); ++i) {
844	      const auto& op = bus.ops[i];
845	      if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
846	          && (op.value & 0xFFFFu) == hybrid::regno_gpr(7)
847	          && ((op.value >> 16) & 1u)) {
848	        const auto& d0 = bus.ops[i - 2];
849	        const auto& d1 = bus.ops[i - 1];
850	        if (d0.reg == kData0 && d0.value == uint32_t(gpa & 0xFFFFFFFFu)
851	            && d1.reg == kData1 && d1.value == uint32_t(gpa >> 32))
852	          return true;
853	      }
854	    }
855	    return false;
856	  };
857	  CHECK(x7_gpa_staged(kScratch));
858	  CHECK(x7_gpa_staged(kScratch + 31ull * HYBRID_VLEN_BYTES_MAX));
859	
860	  // (c)/(d) the sweep runs before the architectural vstart restore (whose
861	  //     vsetvl would otherwise be clobbered) and before the mcycle restore
862	  //     (so the vle8.v insns cannot pollute the resumed counters).
863	  std::optional<std::size_t> vstart_cmd_idx, mcycle_cmd_idx;
864	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
865	    const auto& op = bus.ops[i];
866	    if (op.kind != DmiOp::Kind::Write || op.reg != kCommand) continue;
867	    const auto regno = static_cast<uint16_t>(op.value & 0xFFFFu);
868	    if (!vstart_cmd_idx && regno == hybrid::regno_csr(0x008)) vstart_cmd_idx = i;
869	    if (!mcycle_cmd_idx && regno == hybrid::regno_csr(0xB00)) mcycle_cmd_idx = i;
870	  }
871	  REQUIRE(vstart_cmd_idx.has_value());
872	  REQUIRE(mcycle_cmd_idx.has_value());
873	  CHECK(*last_vle_idx < *vstart_cmd_idx);
874	  CHECK(*last_vle_idx < *mcycle_cmd_idx);
875	}
