1000	TEST_CASE("B9: write_csr_abstract_or_pb busy-poll precedes cmderr inspection")
1001	{
1002	  // The B9 audit claimed write_csr_abstract_or_pb reads abstractcs without
1003	  // first polling busy. In fact write_64bit_register -> write_register_abstract
1004	  // calls poll_until_clear(busy) before returning, so by the time the cmderr
1005	  // check runs, busy is already clear. This test pins that contract: between
1006	  // every kCommand write and the next kAbstractcs read, the recorded ops
1007	  // must include at least one kAbstractcs read (the busy poll). If a future
1008	  // refactor regresses by removing the chained poll, this test fails.
1009	  RecordingBus bus;
