1014	
1015	  // Walk ops; between each kCommand write and the very next kAbstractcs
1016	  // read by an unrelated caller, there must be at least one kAbstractcs
1017	  // read (the busy poll from write_register_abstract).
1018	  bool saw_cmd = false;
1019	  std::size_t reads_since_cmd = 0;
1020	  bool all_cmds_had_abstractcs_poll = true;
1021	  for (const auto& op : bus.ops) {
1022	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand) {
1023	      if (saw_cmd && reads_since_cmd == 0)
1024	        all_cmds_had_abstractcs_poll = false;
1025	      saw_cmd = true;
1026	      reads_since_cmd = 0;
1027	    } else if (saw_cmd && op.kind == DmiOp::Kind::Read
1028	               && op.reg == kAbstractcs) {
1029	      ++reads_since_cmd;
1030	    }
1031	  }
1032	  CHECK(all_cmds_had_abstractcs_poll);
1033	  // The final kCommand write must also be followed by an abstractcs read.
1034	  CHECK(reads_since_cmd > 0u);
