1097	TEST_CASE("L6/L2: S/U resume mirrors the producer's PMP block, addr before cfg")
1098	{
1099	  // With PMP implemented and no matching entry, every S/U access faults
1100	  // (priv spec v1.10) -- an S/U ROI cannot even fetch its first insn on the
1101	  // vsim side unless the producer's PMP block is mirrored in.
1102	  RecordingBus bus;
1103	  bus.dmstatus_value = (1u << 9) | (1u << 17);
1104	
1105	  auto s = rv64_state(0x80001000, 0);
1106	  s.priv = 0;  // U-mode
1107	  for (int i = 0; i < HYBRID_PMP_ADDR_NUM; ++i) s.pmpaddr[i] = 0xb000 + i;
1108	  s.pmpcfg[0] = 0x1f;  // entry 0: NAPOT, RWX
1109	
1110	  hybrid::ResumeDriver driver(bus, kScratch);
1111	  driver.resume(s);
1112	
1113	  std::vector<uint16_t> regnos;
1114	  for (const auto& op : bus.ops)
1115	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
1116	        && ((op.value >> 16) & 1u) != 0u)
1117	      regnos.push_back(static_cast<uint16_t>(op.value & 0xffffu));
1118	
1119	  // All 64 pmpaddr CSRs (0x3B0..0x3EF) and the 8 even pmpcfg CSRs
1120	  // (0x3A0,0x3A2,..,0x3AE -- odd ones do not exist on RV64) are written.
1121	  std::size_t first_cfg = regnos.size(), last_addr = 0;
1122	  std::size_t n_addr = 0, n_cfg = 0, n_odd_cfg = 0;
1123	  for (std::size_t i = 0; i < regnos.size(); ++i) {
1124	    const auto r = regnos[i];
1125	    if (r >= 0x3B0 && r <= 0x3EF) { ++n_addr; last_addr = i; }
1126	    if (r >= 0x3A0 && r <= 0x3AF) {
1127	      if ((r & 1u) != 0u) ++n_odd_cfg;
1128	      else { ++n_cfg; if (i < first_cfg) first_cfg = i; }
1129	    }
1130	  }
1131	  CHECK(n_addr == 64u);
1132	  CHECK(n_cfg == 8u);
1133	  CHECK(n_odd_cfg == 0u);
